def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_defects = sum(1 for _, o in history if o == 'D')
    my_defects = sum(1 for m, _ in history if m == 'D')
    last_m, last_o = history[-1]
    if n < 10:
        if last_o == 'D':
            if opp_defects <= 1 and last_m == 'C':
                return 'C'
            return 'D'
        return 'C'
    if n > 90:
        if opp_defects <= 2:
            return 'C'
        if opp_defects > n * 0.3:
            return 'D'
    if opp_defects == 0:
        return 'C'
    if last_o == 'C':
        if last_m == 'D' and opp_defects >= 4 and opp_defects > my_defects:
            if rng.random() < 0.5:
                return 'D'
        return 'C'
    if n < 30:
        if opp_defects <= max(1, n // 8):
            return 'C'
        return 'D'
    if opp_defects > n * 0.35:
        return 'D'
    if opp_defects > n * 0.12:
        if last_m == 'D' and last_o == 'D':
            recent_def = sum(1 for m, o in history[-4:] if o == 'D')
            if recent_def <= 2 and rng.random() < 0.5:
                return 'C'
        return 'D'
    return 'C'
